    """Complete a diagonal periodic color pattern from its visible seed stripes."""
    h, w = len(grid), len(grid[0])
    colors = {v for row in grid for v in row if v != 0}
    if len(colors) == 1:
        color = next(iter(colors))
        return [[color for _ in range(w)] for _ in range(h)]

    # Every stripe runs along a NW-SE diagonal, whose invariant is col-row.
    stripe_colors = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                d = c - r
                if d in stripe_colors and stripe_colors[d] != color:
                    raise ValueError("inconsistent colors on a diagonal stripe")
                stripe_colors[d] = color

    # The visible seed stripes provide one representative for each phase.
    period = len(stripe_colors)
    phase_colors = {}
    for d, color in stripe_colors.items():
        phase = d % period
        if phase in phase_colors and phase_colors[phase] != color:
            raise ValueError("seed stripes do not define a consistent period")
        phase_colors[phase] = color
    if len(phase_colors) != period:
        raise ValueError("incomplete diagonal phases")

    return [[phase_colors[(c - r) % period] for c in range(w)] for r in range(h)]
